// Написан вручную (сеть: прямой адрес картинки и заголовки CDN — генератор так не умеет).
// spec: .qa/e2e/specs/stories-audience.md 1.1 · кейс .qa/tests/stories-audience/SA-01 · тикет #a85b92
// @data: reg2 создаёт сторис «QA-AUTO sa <время>» и удаляет её в этом же тесте (если упал раньше — удаление в finally).
// Проект data идёт на десктопе — окно iPhone 13 Mini (WebKit) открывается явно через iphoneAs.
// Не проверен на живой странице (записан 10.11 без прогона) — сверить при первом /qa-regress (колонки stories: id, image_url, caption).
import { test, expect } from '@playwright/test';
import { captureApi, restGet, type Row } from '../_shared/api';
import { iphoneAs, closeAs, createStory, deleteOwnStory } from '../stories-viewer/viewer-helpers';

const ROLE = 'reg2';

test.describe('מנגנון חשיפת סיפורים לפי קהל — удалённая сторис', () => {
  test.describe.configure({ timeout: 240_000 });

  test('Удалённая сторис — картинка по прямому адресу недоступна, CDN не отдаёт из кэша @iphone @data (#a85b92)', async ({ browser }) => {
    const page = await iphoneAs(browser, ROLE);
    const caption = `QA-AUTO sa ${new Date().toISOString().slice(0, 16)}`;
    let story: Row | undefined;
    let deleted = false;
    try {
      await createStory(page, caption);
      const api = await captureApi(page, '/discover');
      const res = await restGet(api, `stories?select=id,image_url,caption&author_id=eq.${api.userId}&caption=eq.${encodeURIComponent(caption)}`);
      expect(res.status(), `stories: ${await res.text()}`).toBe(200);
      story = ((await res.json()) as Row[])[0];
      expect(story, `новая сторис «${caption}» найдена у автора`).toBeTruthy();
      const url = String(story!.image_url);

      // Прогреть CDN: дважды без входа — файл доступен.
      const guest = await browser.newContext();
      try {
        for (let i = 0; i < 2; i++) expect((await guest.request.get(url)).status(), `до удаления, запрос ${i + 1}`).toBe(200);

        await deleteOwnStory(page, String(story!.id));
        deleted = true;

        // Реджект Р6 07.11: после удаления адрес не должен отдавать картинку (ни из хранилища, ни из кэша Cloudflare).
        // Программист: через 90 с — 400 NoSuchKey, cf-cache-status BYPASS. Ждём результат, а не фиксированную паузу.
        await expect
          .poll(
            async () => {
              const r = await guest.request.get(url, { failOnStatusCode: false });
              const cache = (r.headers()['cf-cache-status'] ?? '').toUpperCase();
              return r.status() !== 200 && cache !== 'HIT' ? 'недоступна' : `${r.status()} ${cache}`;
            },
            { message: 'картинка удалённой сторис перестала отдаваться', timeout: 150_000, intervals: [5_000, 10_000, 15_000] },
          )
          .toBe('недоступна');
        const last = await guest.request.get(url, { failOnStatusCode: false });
        expect(last.status(), 'картинка удалённой сторис недоступна').not.toBe(200);
        expect((last.headers()['cf-cache-status'] ?? '').toUpperCase(), 'CDN не отдаёт из кэша').not.toBe('HIT');
      } finally {
        await guest.close();
      }
    } finally {
      if (story && !deleted) await deleteOwnStory(page, String(story.id)).catch(() => undefined);
      await closeAs(page, ROLE);
    }
  });
});
